head.script:
scwin.onpageload = function () {

    // 서버의 현재 날짜로 초기값 세팅하기
    var serverDate = $p.getCurrentServerDate();
    ica_exam_1.setValue(serverDate);
    ica_exam_2.setValue(serverDate);
};

/**
 * displayFormat = "yyyy-MM-dd"에서 
 * 버튼 [format이 적용된 값 반환 받기] 클릭 시 호출
 */
scwin.btn_ex1_onclick = function (e) {

    //format이 적용된 값을 넘기는 경우
    var returnValue = ica_exam_1.getDisplayValue();

    // 로그 출력
    let strLog = "getDisplayValue : ' " + returnValue + " '";
    $c.frame.printExampleLog(strLog, txa_log_1, false);
    console.log(strLog);
};

/**
 * displayFormat = "yyyy-MM-dd"에서 
 * 버튼 [format 없이 값 반환 받기] 클릭 시 호출
 */
scwin.btn_ex3_onclick = function (e) {

    //format 없이 값을 넘기는 경우
    var returnValue = ica_exam_1.getValue();

    // 로그 출력
    let strLog = "getValue : ' " + returnValue + " '";
    $c.frame.printExampleLog(strLog, txa_log_1, false);
    console.log(strLog);
};


/**
 * displayFormat = "yyyy : MM : dd"에서 
 * 버튼 [format이 적용된 값 반환 받기] 클릭 시 호출
 */
scwin.btn_ex2_onclick = function (e) {

    //format이 적용된 값을 넘기는 경우
    var returnValue = ica_exam_2.getDisplayValue();

    // 로그 출력
    let strLog = "getDisplayValue : ' " + returnValue + " '";
    $c.frame.printExampleLog(strLog, txa_log_2, false);
    console.log(strLog);
};

/**
 * displayFormat = "yyyy : MM : dd"에서 
 * 버튼 [format 없이 값 반환 받기] 클릭 시 호출
 */
scwin.btn_ex4_onclick = function (e) {

    //format 없이 값을 넘기는 경우
    var returnValue = ica_exam_2.getValue();

    // 로그 출력
    let strLog = "getValue : ' " + returnValue + " '";
    $c.frame.printExampleLog(strLog, txa_log_2, false);
    console.log(strLog);
};

/**
 * 로그 출력용 Textrea의 Value 삭제하기
 */
scwin.btn_clearLog_onclick = function (e) {
    let strTargetId = this.getUserData("userData1");
    let cmpTarget;
    if (strTargetId) {
        cmpTarget = $p.getComponentById(strTargetId) || txa_log;
    } else {
        cmpTarget = txa_log;
    }
    //textarea value를 빈문자열로 할당.
    cmpTarget.setValue("");
};
